    Point3D Heading;
  };

  struct Plane2D
  {
    float_t OrigoDistance;
    Point2D Normal;
  };

  struct Plane3D
  {
    float_t OrigoDistance;
    Point3D Normal;
  };
} // namespace BasicTypesXYZ


namespace OrthoTree
{
  namespace XYAdaptor2D
  {
    using xy_geometry_type = BasicTypesXYZ::float_t;
